"use client";

import * as React from "react";

export interface SplitHeroGlowProps {
  eyebrow?: string;
  title?: string;
  description?: string;
  primaryCta?: { label: string; href?: string; onClick?: () => void };
  secondaryCta?: { label: string; href?: string; onClick?: () => void };
  className?: string;
}

/**
 * SplitHeroGlow — two-column hero with a soft radial glow accent.
 * Mobile collapses to a single column; the glow respects reduced motion.
 */
export function SplitHeroGlow({
  eyebrow = "Modern SaaS",
  title = "Launch your product with code that shines.",
  description = "Pre-engineered components with copy-paste elegance. Toggle styles on the fly.",
  primaryCta = { label: "Get components" },
  secondaryCta = { label: "Studio" },
  className,
}: SplitHeroGlowProps) {
  return (
    <section
      className={[
        "relative py-16 sm:py-24 overflow-hidden bg-background",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute -top-40 left-1/2 -translate-x-1/2 w-[28rem] h-[28rem] rounded-full bg-primary/10 blur-3xl motion-reduce:opacity-50"
      />
      <div className="relative max-w-7xl mx-auto px-6 grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
        <div className="space-y-6">
          <span className="text-xs font-bold text-primary uppercase tracking-[0.18em]">
            {eyebrow}
          </span>
          <h1 className="text-4xl sm:text-5xl lg:text-6xl font-black text-foreground leading-tight">
            {title}
          </h1>
          <p className="text-base text-muted-foreground max-w-md">
            {description}
          </p>
          <div className="flex flex-wrap gap-3">
            <a
              href={primaryCta.href ?? "#"}
              onClick={primaryCta.onClick}
              className="inline-flex items-center justify-center px-5 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold shadow-lg shadow-primary/20 hover:brightness-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/60"
            >
              {primaryCta.label}
            </a>
            <a
              href={secondaryCta.href ?? "#"}
              onClick={secondaryCta.onClick}
              className="inline-flex items-center justify-center px-5 py-2.5 rounded-xl bg-secondary text-foreground text-sm font-semibold border border-border hover:bg-secondary/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/60"
            >
              {secondaryCta.label}
            </a>
          </div>
        </div>
        <div className="relative aspect-[4/3] w-full rounded-2xl border border-border bg-card/40 backdrop-blur-sm" aria-hidden />
      </div>
    </section>
  );
}

export default SplitHeroGlow;
